import mmh3
from bitarray import bitarray

class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bit_array = bitarray(size)
        self.bit_array.setall(0)

    def add(self, item):
        for i in range(self.hash_count):
            digest = mmh3.hash(item, i) % self.size
            self.bit_array[digest] = 1

    def check(self, item):
        for i in range(self.hash_count):
            digest = mmh3.hash(item, i) % self.size
            if self.bit_array[digest] == 0:
                return False
        return True

public class CrawlerWorker {
    public static void executeFetch(List<String> urls) {
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (String url : urls) {
                executor.submit(() -> {
                    // Thread-safe fetch with Virtual Threads allowing 100k+ concurrent connections
                    String content = HttpClient.fetch(url);
                    System.out.println("Fetched: " + url);
                });
            }
        }
    }
}

try-catch fallback mechanics:
1. SSLException / SSLHandshakeException: Malformed certs are ignored and URL marked failed to prevent blocking native workers.
2. Node Crash: The Frontier queue uses a transactional semantic (visiting = in-flight). If the node fails to ACK within 60 seconds, the URL is pushed back to the 'to-visit' queue.
